// Baked mob-config defaults, shipped with the build so every player gets them.
// Generated by the Admin/Debug panel's "Save as game defaults" export, then
// committed by hand. A player's own localStorage overrides still win over these,
// and "Reset to default" on a mob falls back to whatever is baked here.
// Same override shape as js/game/mobconfig.js:
//   { active, rate, biomes: string[]|null, drops: [{item,qty:[min,max],chance}] }
export const MOB_DEFAULTS = {};
